5	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
6	const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão Crédito', debit_card: 'Cartão Débito', cash: 'Dinheiro' };
7	const STATUS_LABELS = { pending: 'Recebido', confirmed: 'Confirmado', preparing: 'Em Preparo', ready: 'Pronto', out_for_delivery: 'Em Entrega', delivered: 'Entregue', canceled: 'Cancelado' };
8	const STATUS_COLORS = { pending: 'bg-yellow-100 text-yellow-800', confirmed: 'bg-blue-100 text-blue-800', preparing: 'bg-orange-100 text-orange-800', ready: 'bg-purple-100 text-purple-800', out_for_delivery: 'bg-indigo-100 text-indigo-800', delivered: 'bg-green-100 text-green-800', canceled: 'bg-red-100 text-red-800' };
9	
10	const today = () => new Date().toISOString().slice(0, 10);
11	const thisMonth = () => new Date().toISOString().slice(0, 7);
12	const thisYear = () => new Date().getFullYear().toString();
13	
14	// BRT (UTC-3) aware date range
15	const startOf = (dateStr) => new Date(dateStr + 'T00:00:00-03:00').toISOString();
16	const endOf = (dateStr) => new Date(dateStr + 'T23:59:59-03:00').toISOString();
17	
18	const lastDayOfMonth = (yearMonth) => {
19	  const [y, m] = yearMonth.split('-').map(Number);
20	  return new Date(y, m, 0).getDate();
21	};
22	
23	const buildRange = (modo, dia, mes, ano, periodoIni, periodoFim) => {
24	  if (modo === 'dia') return { de: startOf(dia), ate: endOf(dia), label: new Date(dia + 'T12:00:00').toLocaleDateString('pt-BR') };
25	  if (modo === 'mes') {
26	    const [y, m] = mes.split('-');
27	    const ld = lastDayOfMonth(mes);
28	    return { de: startOf(`${y}-${m}-01`), ate: endOf(`${y}-${m}-${String(ld).padStart(2, '0')}`), label: new Date(mes + '-01T12:00:00').toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }) };
29	  }
30	  if (modo === 'ano') return { de: startOf(`${ano}-01-01`), ate: endOf(`${ano}-12-31`), label: `Ano ${ano}` };
31	  if (modo === 'periodo') return { de: startOf(periodoIni), ate: endOf(periodoFim), label: `${new Date(periodoIni + 'T12:00:00').toLocaleDateString('pt-BR')} a ${new Date(periodoFim + 'T12:00:00').toLocaleDateString('pt-BR')}` };
32	  return null;
33	};
