35	const printIframe = (html) => {
36	  const iframe = document.createElement('iframe');
37	  iframe.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
38	  document.body.appendChild(iframe);
39	  try { iframe.contentDocument.open(); iframe.contentDocument.write(html); iframe.contentDocument.close(); }
40	  catch { iframe.remove(); const w = window.open('', '_blank'); if (w) { w.document.write(html); w.document.close(); } }
41	};
