172	      <main className="p-6 w-[95%] mx-auto max-w-5xl space-y-5">
173	
174	        {/* Caixa Atual */}
175	        {caixa?.aberto
176	          ? <CaixaAtualPanel caixa={caixa} taxaPagbank={taxaPagbank} onRefresh={carregarDados} />
177	          : caixa && (
