179	              <div className="w-10 h-10 rounded-xl bg-[#F4F4F5] flex items-center justify-center flex-shrink-0">
180	                <Icon name="Lock" size={18} className="text-[#A1A1AA]" />
181	              </div>
182	              <div>
183	                <p className="text-sm font-bold text-[#18181B]">Caixa Fechado</p>
184	                <p className="text-xs text-[#71717A]">Abra o caixa no Dashboard para iniciar uma sessão.</p>
185	              </div>
186	            </div>
187	          )
188	        }
189	
190	        {/* Conferências Pendentes */}
191	        {conferenciasPendentes.length > 0 && (
192	          <div className="bg-white rounded-2xl border border-amber-200 p-5">
