1	import React, { useState, useEffect } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  getMeusProdutos, criarProduto, editarProduto, deletarProduto, toggleProduto,
5	  getMinhasCategorias, getCategoriasGlobais, criarCategoria, deletarCategoria,
6	  getTagsPublicas, listarImpressoras,
7	} from '../../services/restauranteService';
8	import { useAuth } from '../../contexts/AuthContext';
9	import Icon from '../../components/AppIcon';
10	import ImageUpload from '../../components/ui/ImageUpload';
11	import { useMinhaLojaSlug } from '../../hooks/useMinhaLojaSlug';
12	import { useTipoRestaurante } from '../../hooks/useTipoRestaurante';
13	
14	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
15	
16	const EMPTY_FORM = { name: '', description: '', price: '', preco_promo: '', image_url: '', category_id: '', tags: [], destaque: false, impressora_id: '' };
17	
18	const TagBadge = ({ slug, tagsMap }) => {
19	  const t = tagsMap[slug];
20	  if (!t) return <span className="text-xs px-1.5 py-0.5 rounded font-bold bg-gray-100 text-gray-600">{slug}</span>;
21	  return <span className="text-xs px-1.5 py-0.5 rounded font-bold bg-orange-100 text-orange-700">{t.name}</span>;
22	};
23	
24	const RestauranteProdutos = () => {
25	  const navigate = useNavigate();
26	  const { signOut } = useAuth();
27	  const [produtos, setProdutos] = useState([]);
28	  const [categorias, setCategorias] = useState([]);
29	  const [categoriasGlobais, setCategoriasGlobais] = useState([]);
30	  const [tagsDisponiveis, setTagsDisponiveis] = useState([]); // tags não-auto do admin
31	  const [impressoras, setImpressoras] = useState([]);
32	  const tipoRestaurante = useTipoRestaurante();
33	  const [novaCategoria, setNovaCategoria] = useState('');
34	  const [criandoCateg, setCriandoCateg] = useState(false);
35	  const [deletandoCateg, setDeletandoCateg] = useState(null);
36	  const [showCategPanel, setShowCategPanel] = useState(false);
37	  const [loading, setLoading] = useState(true);
38	  const [erro, setErro] = useState(null);
39	  const [showModal, setShowModal] = useState(false);
40	  const [editando, setEditando] = useState(null);
41	  const [form, setForm] = useState(EMPTY_FORM);
42	  const [salvando, setSalvando] = useState(false);
43	  const [deletando, setDeletando] = useState(null);
44	
45	  const carregar = () => {
46	    setLoading(true);
47	    Promise.all([getMeusProdutos(), getMinhasCategorias(), getCategoriasGlobais(), getTagsPublicas()])
48	      .then(([p, mine, global, tagsResp]) => {
49	        setProdutos(p.produtos ?? []);
50	        setCategorias(mine.categorias ?? []);
51	        setCategoriasGlobais(global.categorias ?? []);
52	        // Só tags manuais (is_auto=false) — restaurante pode atribuir
53	        setTagsDisponiveis((tagsResp.tags ?? []).filter((t) => !t.is_auto));
54	      })
55	      .catch((e) => setErro(e.message))
56	      .finally(() => setLoading(false));
57	  };
58	
59	  useEffect(() => { carregar(); }, []);
60	  useEffect(() => { if (tipoRestaurante) listarImpressoras().then(setImpressoras).catch(() => {}); }, [tipoRestaurante]);
61	
62	  const abrirNovo = () => {
63	    setEditando(null);
64	    setForm(EMPTY_FORM);
65	    setShowModal(true);
66	  };
67	
68	  const abrirEditar = (p) => {
69	    setEditando(p);
70	    setForm({
71	      name: p.name ?? '',
72	      description: p.description ?? '',
73	      price: p.price != null ? String(p.price) : '',
74	      preco_promo: p.preco_promo != null ? String(p.preco_promo) : '',
75	      image_url: p.image_url ?? '',
76	      category_id: p.category_id != null ? String(p.category_id) : '',
77	      tags: Array.isArray(p.tags) ? p.tags : [],
78	      destaque: p.destaque ?? false,
79	      impressora_id: p.impressora_id != null ? String(p.impressora_id) : '',
80	    });
81	    setShowModal(true);
82	  };
83	
84	  const handleCriarCategoria = async (e) => {
85	    e.preventDefault();
86	    if (!novaCategoria.trim()) return;
87	    setCriandoCateg(true);
88	    try {
89	      const nova = await criarCategoria(novaCategoria.trim());
90	      setCategorias((prev) => [...prev, nova].sort((a, b) => a.name.localeCompare(b.name)));
91	      setNovaCategoria('');
92	    } catch (err) {
93	      alert(err.message);
94	    } finally {
95	      setCriandoCateg(false);
96	    }
97	  };
98	
99	  const handleDeletarCategoria = async (cat) => {
100	    if (!window.confirm(`Deletar categoria "${cat.name}"? Os produtos ligados perderão esta categoria.`)) return;
101	    setDeletandoCateg(cat.id);
102	    try {
103	      await deletarCategoria(cat.id);
104	      setCategorias((prev) => prev.filter((c) => c.id !== cat.id));
105	    } catch (err) {
106	      alert(err.message);
107	    } finally {
108	      setDeletandoCateg(null);
109	    }
110	  };
111	
112	  const fecharModal = () => {
113	    setShowModal(false);
114	    setEditando(null);
115	    setForm(EMPTY_FORM);
116	  };
117	
118	  const toggleTag = (tag) => {
119	    setForm((f) => ({
120	      ...f,
121	      tags: f.tags.includes(tag) ? f.tags.filter((t) => t !== tag) : [...f.tags, tag],
122	    }));
123	  };
124	
125	  const handleToggle = async (produto) => {
126	    try {
127	      const atualizado = await toggleProduto(produto.id, !produto.is_active);
128	      setProdutos((prev) => prev.map((p) => (p.id === produto.id ? { ...p, is_active: atualizado.is_active } : p)));
129	    } catch (e) {
130	      alert(e.message);
131	    }
132	  };
133	
134	  const handleSalvar = async (e) => {
135	    e.preventDefault();
136	    if (!form.name || !form.price || !form.category_id) {
137	      alert('Nome, preço e categoria são obrigatórios');
138	      return;
139	    }
140	    setSalvando(true);
141	    const payload = {
142	      name: form.name,
143	      description: form.description || null,
144	      price: parseFloat(form.price),
145	      preco_promo: form.preco_promo ? parseFloat(form.preco_promo) : null,
146	      image_url: form.image_url || null,
147	      category_id: parseInt(form.category_id),
148	      tags: form.tags,
149	      destaque: form.destaque,
150	      impressora_id: form.impressora_id ? parseInt(form.impressora_id) : null,
151	    };
152	    try {
153	      if (editando) {
154	        const atualizado = await editarProduto(editando.id, payload);
155	        setProdutos((prev) => prev.map((p) => (p.id === editando.id ? atualizado : p)));
156	      } else {
157	        const novo = await criarProduto(payload);
158	        setProdutos((prev) => [...prev, novo]);
159	      }
160	      fecharModal();
161	    } catch (e) {
162	      alert(e.message);
163	    } finally {
164	      setSalvando(false);
165	    }
166	  };
167	
168	  const handleDeletar = async (produto) => {
169	    if (!window.confirm(`Deletar "${produto.name}"? Esta ação não pode ser desfeita.`)) return;
170	    setDeletando(produto.id);
171	    try {
172	      await deletarProduto(produto.id);
173	      setProdutos((prev) => prev.filter((p) => p.id !== produto.id));
174	    } catch (e) {
175	      alert(e.message);
176	    } finally {
177	      setDeletando(null);
178	    }
179	  };
180	
181	  const catMap = Object.fromEntries(
182	    [...categorias, ...categoriasGlobais].map((c) => [c.id, c.name])
183	  );
184	  const tagsMap = Object.fromEntries(tagsDisponiveis.map((t) => [t.slug, t]));
185	  // Identifica se alguma tag de promoção está ativa (slug contém 'promo')
186	  const temPromo = form.tags.some((s) => s.includes('promo'));
187	
188	  const links = [
189	    { label: 'Dashboard', path: '/restaurante' },
190	    { label: 'Delivery', path: '/restaurante/delivery' },
191	    { label: 'Produtos', path: '/restaurante/produtos' },
192	    { label: 'Combos', path: '/restaurante/combos' },
193	    { label: 'Pedidos', path: '/restaurante/pedidos' },
194	    { label: 'Entregas', path: '/restaurante/entregas' },
195	    ...(tipoRestaurante ? [
196	      { label: 'Salão', path: '/restaurante/salao' },
197	      { label: 'Garçons', path: '/restaurante/garcons' },
198	      { label: 'Impressoras', path: '/restaurante/impressoras' },
199	    ] : []),
200	    { label: 'Clientes', path: '/restaurante/clientes' },
201	    { label: 'Designer', path: '/restaurante/aparencia' },
202	    { label: 'Config', path: '/restaurante/config' },
203	  ];
204	  const slugLoja = useMinhaLojaSlug();
205	
206	  return (
207	    <div className="min-h-screen bg-[#FAFAFA]">
208	      <header className="bg-white border-b border-[#E4E4E7] px-6 py-4 flex items-center justify-between">
209	        <h1 className="text-xl font-bold text-[#18181B]">Produtos</h1>
210	        <nav className="flex gap-1.5 flex-wrap">
211	          {links.map((l) => (
212	            <button key={l.path} onClick={() => navigate(l.path)}
213	              className={`px-3 py-2 text-sm font-semibold rounded-lg transition-colors ${
214	                l.path === '/restaurante/produtos'
215	                  ? 'text-white bg-[#FF441F] shadow-sm shadow-[#FF441F]/30'
216	                  : 'text-[#27272A] hover:bg-[#F4F4F5]'
217	              }`}>
218	              {l.label}
219	            </button>
220	          ))}
221	          {slugLoja && (
222	            <button onClick={() => window.open(`/r/${slugLoja}`, '_blank')}
223	              className="px-3 py-2 text-sm font-semibold rounded-lg text-green-700 bg-green-50 hover:bg-green-100 border border-green-200 flex items-center gap-1.5">
224	              <Icon name="ExternalLink" size={14} /> Loja
225	            </button>
226	          )}
227	          <button onClick={async () => { await signOut(); navigate('/customer-registration-login'); }}
228	            className="px-3 py-2 text-sm font-semibold text-red-600 hover:bg-red-50 rounded-lg border border-red-200">
229	            Sair
230	          </button>
231	        </nav>
232	      </header>
233	
234	      <main className="p-6 max-w-4xl mx-auto">
235	        {erro && <p className="text-red-600 mb-4 text-sm">{erro}</p>}
236	
237	        {/* Painel de categorias do restaurante */}
238	        <div className="bg-white rounded-xl border border-[#E4E4E7] mb-5">
239	          <button
240	            type="button"
241	            onClick={() => setShowCategPanel((v) => !v)}
242	            className="w-full flex items-center justify-between px-5 py-3.5 text-left"
243	          >
244	            <div className="flex items-center gap-2">
245	              <span className="font-semibold text-[#18181B] text-sm">Minhas Categorias</span>
246	              <span className="text-xs text-[#71717A] bg-[#F4F4F5] px-2 py-0.5 rounded-full">{categorias.length}</span>
247	            </div>
248	            <span className="text-[#71717A] text-xs">{showCategPanel ? '▲' : '▼'}</span>
249	          </button>
250	
251	          {showCategPanel && (
252	            <div className="px-5 pb-4 border-t border-[#F4F4F5]">
253	              {/* Criar nova */}
254	              <form onSubmit={handleCriarCategoria} className="flex gap-2 mt-3 mb-4">
255	                <input
256	                  value={novaCategoria}
257	                  onChange={(e) => setNovaCategoria(e.target.value)}
258	                  placeholder="Nome da nova categoria..."
259	                  className="flex-1 border border-[#E4E4E7] rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]"
260	                />
